// Primitives: assignment copies the VALUE — two independent boxes
let score = 42;
let scoreCopy = score;
scoreCopy = 100;
console.log(score); // 42 — the original never heard about it

// Objects: assignment copies the REFERENCE — two labels, one box
const profile = { name: 'Ada', level: 'advanced' };
const alias = profile; // no new object — a second name for the SAME one
alias.level = 'mentor';
console.log(profile.level);     // "mentor" — one object, two names
console.log(profile === alias); // true — same identity

function applyDiscount(order, percent) {
  order.total = order.total * (1 - percent / 100); // writes through the reference
  return order;                                     // and hands the SAME object back
}

const order = { total: 200 };
const discounted = applyDiscount(order, 20);

console.log(order.total);          // 160 — the caller's object changed
console.log(discounted === order); // true — "returned a new order" was an illusion

const a = { id: 1 };
const b = { id: 1 };
const c = a;

console.log(a === b); // false — same shape, different objects: === asks "same one?"
console.log(a === c); // true  — one object, two names
console.log([1, 2] === [1, 2]); // false — arrays are objects too

// The contents comparison people reach for — and its fine print:
console.log(JSON.stringify(a) === JSON.stringify(b)); // true... this once
const p = { id: 1, role: 'dev' };
const q = { role: 'dev', id: 1 };
console.log(JSON.stringify(p) === JSON.stringify(q)); // false — property ORDER differs

const original = { title: 'TS Basics', hours: 8 };

const spreadCopy = { ...original };             // spread: copies own enumerable properties
const assignCopy = Object.assign({}, original); // same semantics, older syntax

spreadCopy.title = 'TS Deep Dive';
console.log(original.title); // "TS Basics" — the top level is now independent
console.log(spreadCopy.title, '|', assignCopy.title); // "TS Deep Dive | TS Basics"

const noisy = { id: 1, nickname: undefined, save: () => 'saved', when: new Date(0), score: NaN };
const roundTripped = JSON.parse(JSON.stringify(noisy));

console.log(JSON.stringify(Object.keys(roundTripped))); // ["id","when","score"]
console.log(typeof roundTripped.when);                  // "string" — Dates serialize to text
console.log(roundTripped.score);                        // null — NaN has no JSON form

const course = { title: 'TS Basics', meta: { hours: 8, tags: ['ts'] }, updated: new Date(0) };

const deep = structuredClone(course);
deep.meta.hours = 99;               // nested object...
deep.meta.tags.push('advanced');    // ...nested INSIDE an array — still isolated

console.log(course.meta.hours);            // 8
console.log(course.meta.tags.join(','));   // "ts"
console.log(deep.updated instanceof Date); // true — Dates survive as Dates
console.log(deep.meta === course.meta);    // false — every level is new

try {
  structuredClone({ save: () => 'saved' }); // functions are not cloneable data
} catch (e) {
  console.log(e.name); // "DataCloneError" — it throws instead of silently dropping
}

