const original = {
  title: "SQL Fundamentals",
  meta: { hours: 12, level: "beginner" },
};

// 1) Reference sharing: assignment copies the REFERENCE, not the object
const alias = original;
alias.meta.hours = 99;
console.log("after alias mutation, original.meta.hours:", original.meta.hours);

// 2) Shallow copy: top-level properties become independent...
const copy = { ...original };
copy.title = "SQL Advanced";
console.log("original.title:", original.title);
console.log("copy.title:", copy.title);

// 3) ...but NESTED objects are still shared
copy.meta.level = "advanced";
console.log("original.meta.level:", original.meta.level);
console.log("copy.meta.level:", copy.meta.level);

console.log("takeaway: spread copies ONE level - nested objects stay shared; structuredClone() makes a true deep copy");

