const settings = { theme: 'dark', limits: { retries: 3, timeout: 5000 } };

// Pure: build a new object at every level we touch, return it, mutate nothing
function raiseRetries(config) {
  return { ...config, limits: { ...config.limits, retries: 5 } };
}

const updated = raiseRetries(settings);
console.log('settings.limits.retries:', settings.limits.retries); // 3 — untouched
console.log('updated.limits.retries:', updated.limits.retries);   // 5
console.log('updated === settings:', updated === settings);       // false — genuinely new

const backup = structuredClone(settings); // deep: every level independent
backup.limits.retries = 9;
console.log('after backup mutation, settings.limits.retries:', settings.limits.retries); // 3

